class CosmosQuery
{
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL — still works because we kept "Discriminator" (see ProductContext).
        // If we had NOT configured HasDiscriminator("Discriminator"), EF9 would write "$type"
        // and this query would silently return zero results against old documents.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        // EF Core 9 removed synchronous query APIs for Cosmos (ToList, First, Single, etc.).
        // All queries must use async: ToListAsync, FirstAsync, etc.
        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

